def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    groups = []
    current_group = ''
    for char in paren_string:
        if char == '(':
            if current_group:
                groups.append(current_group)
            current_group = '('
        elif char == ')':
            current_group += ')'
            groups.append(current_group)
            current_group = ''

    return [group.replace(' ', '') for group in groups if is_balanced(group)]

